import clsx from 'clsx';
import React, { forwardRef } from 'react';
import { isElement } from 'react-is';

import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { actionsSlotCss } from '../EmptyState.sty.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface EmptyStateActionsProps
  extends WithChildren,
    StylingProps,
    DataTestId {}
//#endregion Typings

/**
 * Typeguard function that will check if a React.Node is a EmptyState.Actions
 * @internal
 */
export function _isEmptyStateActions(
  child: React.ReactNode,
): child is React.ReactElement<EmptyStateActionsProps> {
  return isElement(child) && child.type === Actions;
}

/** The actions slot of the EmptyState component. */
export const Actions = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  EmptyStateActionsProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  return (
    <Flex
      ref={forwardedRef}
      flexDirection="row"
      alignItems="center"
      gap={8}
      className={clsx([actionsSlotCss, consumerClassName])}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </Flex>
  );
});

(Actions as typeof Actions & { displayName: string }).displayName =
  'EmptyState.Actions';
